// Üretilen dosya: tool/ozgun/uret.py. Matematik · Sayma, olasılık ve kombinatorik problemleri (orta).
const ozMathematics14Orta = <(String, String, List<String>, String)>[
  ('A kentinden B kentine 3 yol, B\'den C\'ye 2 yol vardır; ayrıca A\'dan C\'ye B\'ye uğramayan 4 doğrudan yol bulunur. A\'dan C\'ye toplam kaç farklı yolla gidilebilir?', '10', ['9', '24', '14'], 'B üzerinden 3 · 2 = 6 yol, doğrudan 4 yol vardır. İki durum ayrık olduğundan 6 + 4 = 10 bulunur.'),
  ('5! + 4! toplamı aşağıdaki ifadelerden hangisine eşittir?', '6 · 4!', ['9!', '5! · 4!', '(5 + 4)!'], '5! = 5 · 4! olduğundan 5! + 4! = 4!(5 + 1) = 6 · 4!. Faktöriyeller toplanırken sayılar toplanamaz.'),
  ('4 farklı ödül 3 öğrenci arasında, bir öğrenci birden fazla ödül alabilecek biçimde kaç farklı şekilde dağıtılabilir?', '81', ['64', '12', '24'], 'Her ödül için 3 öğrenci seçeneği vardır: 3⁴ = 81. Öğrencilere ödül seçmeye kalksaydık 4³ = 64 yanlış sonucuna varırdık.'),
  ('1, 2, 3, 4, 5 rakamlarıyla, rakamları tekrarsız yazılan üç basamaklı sayıların kaç tanesi 300\'den büyüktür?', '36', ['48', '24', '60'], 'Yüzler basamağı 3, 4 ya da 5 olabilir (3 seçenek); kalan iki basamak kalan 4 rakamdan 4 · 3 = 12 biçimde seçilir. 3 · 12 = 36.'),
  ('Okunuşu ters çevrildiğinde değişmeyen (örneğin 484) üç basamaklı kaç doğal sayı vardır?', '90', ['81', '100', '99'], 'Yüzler basamağı 1–9 arasında 9 seçenek, onlar basamağı 10 seçenek; birler basamağı yüzlerle aynı olur. 9 · 10 = 90.'),
  ('Permütasyon tanımında, 9 elemanlı bir kümeden hiç eleman seçilmeden oluşturulan sıralamaların sayısını veren P(9, 0) değeri kaçtır?', '1', ['0', '9', 'Tanımsızdır'], 'n elemandan hiç eleman seçilmeyen sıralamanın tek bir biçimi (boş dizi) vardır; P(n, 0) = 1 olarak tanımlanır.'),
  ('6 farklı kitap bir rafa dizilecektir. İki özel baskı kitabı rafın iki ucuna konacağına göre kaç farklı dizilim yapılabilir?', '48', ['24', '120', '12'], 'Özel kitaplar uçlara 2! = 2 biçimde yerleşir; diğer 4 kitap ortaya 4! = 24 biçimde dizilir. 2 · 24 = 48.'),
  ('5 kişilik bir grup sırayla konuşma yapacaktır. Ali\'nin Berk\'ten önce konuşması koşuluyla kaç farklı konuşma sırası oluşturulabilir?', '60', ['120', '24', '30'], 'Toplam 5! = 120 sıralamanın yarısında Ali, diğer yarısında Berk öndedir; 120/2 = 60.'),
  ('MARMARA sözcüğünün harfleriyle kaç farklı dizilim oluşturulabilir?', '210', ['420', '840', '5040'], 'Yedi harften M iki, A üç, R iki kez geçer: 7!/(2! · 3! · 2!) = 5040/24 = 210.'),
  ('ANKARA sözcüğünün harfleri yer değiştirilerek A harfi ile başlayan kaç farklı dizilim yazılabilir?', '60', ['120', '30', '20'], 'Baştaki A sabitlenince N, K, A, R, A harfleri kalır; bunlarda A iki kez tekrar eder: 5!/2! = 60.'),
  ('TÜRKİYE sözcüğünde üç sesli harf (Ü, İ, E) bulunur. Bu harflerin hepsinin yan yana olduğu kaç farklı dizilim yazılabilir?', '720', ['5040', '1440', '360'], 'Sesli harfler bir blok sayılırsa 5 öğe 5! = 120 biçimde dizilir; blok içinde 3! = 6 düzen vardır. 120 · 6 = 720.'),
  ('6 kişi yuvarlak bir masa etrafına oturacaktır. İki arkadaşın yan yana oturmadığı kaç farklı düzen vardır?', '72', ['48', '120', '96'], 'Toplam (6 − 1)! = 120 düzen vardır. Yan yana oturma durumları 2 · 4! = 48 tanedir. 120 − 48 = 72.'),
  ('3 erkek ve 4 kadın yuvarlak bir masa etrafına, erkekler birbirine bitişik olacak biçimde kaç farklı oturabilir?', '144', ['720', '288', '120'], 'Erkek bloğu tek kişi sayılırsa 5 öğe (5 − 1)! = 24 biçimde oturur; blok içi 3! = 6 düzen vardır. 24 · 6 = 144.'),
  ('Bir kulüpte n üyeden üçer kişilik heyetler seçiliyor ve toplam 35 farklı heyet kurulabiliyor. C(n, 3) = 35 olduğuna göre kulüpte kaç üye vardır?', '7', ['6', '8', '14'], 'n(n − 1)(n − 2)/6 = 35 ise çarpım 210\'dur; 7 · 6 · 5 = 210 olduğundan n = 7 bulunur.'),
  ('C(12, x + 1) = C(12, 2x − 2) eşitliğini sağlayan x değeri kaçtır?', '3', ['4', '5', '13/3'], 'Eşit kombinasyonlarda alt değerler ya eşittir ya da toplamları 12\'dir. x + 1 = 2x − 2 ise x = 3; toplam koşulu 3x − 1 = 12 ise tam sayı vermez. x = 3, C(12, 4) olur.'),
  ('12 öğrenci, her biri 4 kişilik ve ayrı adlar taşıyan (Kartal, Şahin, Atmaca) üç takıma kaç farklı biçimde ayrılabilir?', '34650', ['5775', '346500', '27720'], 'İlk takım C(12, 4) = 495, ikinci takım C(8, 4) = 70, üçüncü takım C(4, 4) = 1 biçimde seçilir; 495 · 70 = 34650.'),
  ('7 doktor ve 5 hemşire arasından, en çok 1 doktor bulunmak koşuluyla 4 kişilik bir sağlık ekibi kaç farklı biçimde seçilebilir?', '75', ['70', '35', '105'], 'Hiç doktor yoksa C(5, 4) = 5; bir doktor varsa 7 · C(5, 3) = 70. Toplam 5 + 70 = 75.'),
  ('Bir torbada 4 kırmızı ve 6 mavi, birbirinden ayırt edilebilen 10 top vardır. Aynı anda çekilen 3 topun en az birinin kırmızı olduğu kaç farklı çekiliş vardır?', '100', ['1000', '80', '84'], 'Tüm çekilişler C(10, 3) = 120\'dir; hiç kırmızı olmayanlar C(6, 3) = 20\'dir. 120 − 20 = 100.'),
  ('5 kız ve 5 erkek arasından, içinde en az 2 kız bulunan 4 kişilik bir kurul kaç farklı biçimde oluşturulabilir?', '155', ['1550', '160', '150'], 'Toplam C(10, 4) = 210\'dur. Hiç kız yoksa C(5, 4) = 5, bir kız varsa 5 · C(5, 3) = 50 durum elenir. 210 − 55 = 155.'),
  ('Aynı doğru üzerinde 5 nokta, bu doğrunun dışında ise 4 nokta vardır. Doğru dışındaki 4 nokta ve karışık üçlüler arasında başka doğrusallık yoktur. Köşeleri bu 9 nokta olan kaç farklı üçgen çizilebilir?', '74', ['84', '79', '64'], 'Tüm üçlüler C(9, 3) = 84\'tür. Aynı doğrudaki 5 noktadan oluşan üçlüler C(5, 3) = 10 tanedir ve üçgen oluşturmaz. 84 − 10 = 74.'),
  ('İki paralel doğrunun birinde 5, diğerinde 4 nokta işaretlenmiştir. Köşeleri bu noktalar olan kaç farklı üçgen çizilebilir?', '70', ['84', '60', '126'], 'İki köşe 5\'li doğrudan, bir köşe 4\'lü doğrudan: C(5, 2) · 4 = 40. İki köşe 4\'lü doğrudan, bir köşe 5\'liden: C(4, 2) · 5 = 30. Toplam 70.'),
  ('Bir satranç tahtasındaki 8 × 8 kare ızgara üzerinde, kenarları ızgara çizgileri boyunca uzanan kaç farklı dikdörtgen (kareler dahil) bulunur?', '1296', ['12960', '1024', '784'], '9 yatay çizgiden 2\'si ve 9 dikey çizgiden 2\'si seçilir: C(9, 2)² = 36² = 1296.'),
  ('x + y + z + t = 12 denklemini sağlayan pozitif tam sayı dörtlüleri (x, y, z, t) kaç tanedir?', '165', ['220', '1650', '330'], 'Her değişkenden 1 çıkarıp negatif olmayan çözümlere dönüştüren yöntemle C(12 − 1, 4 − 1) = C(11, 3) = 165 bulunur.'),
  ('x + y + z = 12 denkleminin, her değişkenin en az 2 olduğu tam sayı çözümü kaç tanedir?', '28', ['66', '280', '45'], 'x = a + 2 vb. dönüşümüyle a + b + c = 6 elde edilir; negatif olmayan çözüm sayısı C(8, 2) = 28.'),
  ('(3x − 2y)⁴ açılımında x²y² terimlerinin katsayısı kaçtır?', '216', ['144', '−216', '864'], 'C(4, 2) · (3x)² · (−2y)² = 6 · 9 · 4 · x²y² = 216 x²y². Çift kuvvetten dolayı işaret pozitiftir.'),
  ('(1 + x)¹⁰ açılımında katsayısı en büyük olan terim kaçıncı terimdir?', '6', ['5', '7', '10'], 'Binom katsayıları n çift olduğunda ortadaki C(10, 5) = 252 değerinde en büyüktür; bu terim açılımda 6. sıradadır.'),
  ('Pascal üçgeninin 6. satırı (0. satır = 1) için tek sıradaki terimlerin, yani 1., 3., 5. ve 7. terimlerin toplamı kaçtır?', '32', ['64', '16', '128'], 'C(6,0) + C(6,2) + C(6,4) + C(6,6) = 1 + 15 + 15 + 1 = 32. Genel olarak tek sıradaki terimler toplamı 2ⁿ⁻¹ olduğundan 2⁵ = 32 bulunur.'),
  ('720 sayısının pozitif tam bölenlerinin kaç tanesi tek sayıdır?', '6', ['30', '15', '12'], '720 = 2⁴ · 3² · 5 olur. Tek bölenler 2\'siz çarpanlardan gelir: (2 + 1)(1 + 1) = 6.'),
  ('Aşağıdaki sayılardan hangisinin pozitif bölen sayısı tektir?', '36', ['360', '30', '35'], 'Bölen sayısı yalnız tam kareler için tektir. 36 = 2² · 3² olduğundan (2 + 1)(2 + 1) = 9 bölenlidir; diğerleri tam kare değildir.'),
  ('Bir torbada 10 sarı, 8 mavi ve 6 kırmızı bilye vardır. Bakmadan çekilen bilyeler arasında aynı renkten en az 3 bilyenin bulunması için en az kaç bilye çekmek gerekir?', '7', ['9', '6', '19'], 'En kötü durumda her renkten 2 bilye çekilir (6 bilye). Bir sonraki bilye mutlaka bir rengi 3\'e tamamlar: 7.'),
